changeSet.sql:
INSERT INTO base_permissions (name, code, sub_module_id, enabled) SELECT 'Forzar solape de citas', 'appointment.overlap.force', bp.sub_module_id, 1 FROM base_permissions bp WHERE bp.code = 'appointment.create' AND NOT EXISTS ( SELECT 1 FROM base_permissions WHERE code = 'appointment.overlap.force');
INSERT INTO base_role_permissions (base_role_id, base_permission_id, enabled) SELECT br.id, bp.id, 1 FROM base_roles br JOIN base_permissions bp ON bp.code = 'appointment.overlap.force' WHERE br.code = 'ADMIN' AND NOT EXISTS ( SELECT 1 FROM base_role_permissions brp WHERE brp.base_role_id = br.id AND brp.base_permission_id = bp.id);
INSERT INTO permissions (name, code, company_id, sub_module_id, enabled) SELECT bp.name, bp.code, c.id, bp.sub_module_id, 1 FROM companies c CROSS JOIN base_permissions bp WHERE bp.code = 'appointment.overlap.force' AND NOT EXISTS ( SELECT 1 FROM permissions p WHERE p.company_id = c.id AND p.code = bp.code);
INSERT INTO role_permissions (role_id, permission_id, enabled) SELECT r.id, p.id, 1 FROM roles r JOIN permissions p ON p.company_id = r.company_id AND p.code = 'appointment.overlap.force' WHERE r.code = 'ADMIN' AND NOT EXISTS ( SELECT 1 FROM role_permissions rp WHERE rp.role_id = r.id AND rp.permission_id = p.id);

changeSet.rollback:
DELETE FROM role_permissions
WHERE permission_id IN (
    SELECT id FROM permissions WHERE code = 'appointment.overlap.force');

DELETE FROM permissions WHERE code = 'appointment.overlap.force';

DELETE FROM base_role_permissions
WHERE base_permission_id IN (
    SELECT id FROM base_permissions WHERE code = 'appointment.overlap.force');

DELETE FROM base_permissions WHERE code = 'appointment.overlap.force';
